%[text] **1. Time Response/Model Estimation & Stability** (35 marks)
%[text] Consider the unit step response of a 2nd order system shown below.
t_final=1.5 %[output:3020b9c3]
load("dataFinal23.mat")
plot(t_Q1,y_Q1) %[output:7b3e7694]
xlabel('Time (s)') %[output:7b3e7694]
ylabel('Output') %[output:7b3e7694]
title('Unit Step Response') %[output:7b3e7694]
%[text] ![](text:image:875a)
%[text] a) (5 marks)  Is the system overdamped, critically damped or underdamped? (Uncomment the correct answer below)
% Uncomment the correct answer
%Q1aSystemIsOverDamped=true
%Q1aSystemIsCriticallyDamped=true
Q1aSystemIsUnderDamped=true %[output:5cdab48f]
%[text] What are the settling time, peak time and % overshoot of the system?
% --- Compute Peak Time ---
[peakValue, peakIndex] = max(y_Q1);
Tp_Q1 = t_Q1(peakIndex);

% --- Compute Percent Overshoot ---
finalValue = y_Q1(end);
POS_Q1 = (peakValue - finalValue) / finalValue * 100;

% --- Compute Settling Time (2% criterion) ---
tolerance = 0.02 * finalValue;
lowerBound = finalValue - tolerance;
upperBound = finalValue + tolerance;

% Find the last time the signal leaves the 2% band
idx = find(y_Q1 < lowerBound | y_Q1 > upperBound);

if isempty(idx)
    Ts_Q1 = 0;  % Already settled
else
    Ts_Q1 = t_Q1(idx(end));
end

% --- Compute Rise Time ---
% find the index of the first entry
Tr_Q1 = t_Q1(find(y_Q1 >= 0.9 * finalValue, 1)) - t_Q1(find(y_Q1 >= 0.1 * finalValue, 1)); 

% Display results
Tr_Q1 % rise time %[output:8429c511]
Ts_Q1 % settling time %[output:7a2e572d]
Tp_Q1 % peak time %[output:5be5cea2]
POS_Q1 % POS_Q1 / 100 would convert it to fraction %[output:1a00f7b2]
%[text] 
%[text] b) (5 marks) From the above data and plot for the step response, what are the damping ratio $\\zeta$ and natural frequency $\\omega\_n$ of system? 
PO = POS_Q1 / 100;                         % convert to fraction
zeta_Q1 = -log(PO) / sqrt(pi^2 + log(PO)^2);
omega_n_Q1 = pi / (Tp_Q1 * sqrt(1 - zeta_Q1^2));

y_ss_Q1 = y_Q1(end);                       % steady-state value from data

zeta_Q1 %[output:7f3aaa63]
omega_n_Q1 %[output:66d66b15]
y_ss_Q1 %[output:44d022ac]
%[text] c) (5 marks)  Estimate the transfer function for the closed loop plant that generated the above step response.
% --- Closed-loop 2nd-order model: Gcl(s) = K*wn^2 / (s^2 + 2*zeta*wn*s + wn^2)
K_cl      = y_ss_Q1;     % DC gain matches steady-state output to unit step
num_Q1    = K_cl * omega_n_Q1^2;
den_Q1    = [1  2*zeta_Q1*omega_n_Q1  omega_n_Q1^2];

Gcl_Q1    = tf(num_Q1, den_Q1);   % estimated closed-loop TF

% Your code goes here
Gcl_Q1 %[output:6c12b95b]

% plot the original data and the step response
% of the approximation

plot(t_Q1,y_Q1) %[output:8a27a51d]
hold on %[output:8a27a51d]
step(Gcl_Q1,t_final) %[output:8a27a51d]
hold off %[output:8a27a51d]
