%[text] f) (5 marks) For what values of K is the closed loop system you computed in part [1(e)](internal:M_DEBBC93E) stable?  Justify your answer using matlab and explanation.
%% Part 1(f) – Stability range in K

s = tf('s');

% Plant and controller (same as 1e, but using a placeholder value for K, which is K = 1, to sketch root locus for K > 0)
G = (s + 1) / (s^4 + 15*s^3 + 50*s^2 + 189*s + 200);
D = (s + 0.1) / s;

% Open-loop transfer function L(s) = D(s)G(s)
L = D * G;

% Use MATLAB's rlocus to sample pole locations for many K values
