%[text] c) (5 marks) If you want to design a closed loop control system that results in a step response with 4.32% overshoot and 4 second settling time, assuming ideal 2nd order behaviour, what would be the new location for the dominant poles?
% Your code goes here
% Desired performance
Mp = 0.0432;   % 4.32% overshoot
Ts = 4;        % 4-second settling time (2% criterion)

syms zeta

% Overshoot equation: Mp = exp(-pi*zeta/sqrt(1 - zeta^2))
eq = Mp == exp(-pi*zeta/sqrt(1 - zeta^2));

% Solve for zeta in the valid range (0 < zeta < 1)
zeta_val = double(vpasolve(eq, zeta, [0 1]));

% Natural frequency from Ts = 4/(zeta*wn)
wn = 4/(zeta_val * Ts);

% Dominant poles
sigma = -zeta_val * wn;
wd    = wn * sqrt(1 - zeta_val^2);

% Final answer: dominant pole pair
s_d = [sigma + 1i*wd; sigma - 1i*wd] %[output:08659e35]
%[text] d) (5 marks) Design a PD compensator $D(s)=K\\left (s+z\_c\\right)$ to place the dominant poles at the location you computed in part (c). Assign your answer the variable $\\texttt{D\\\_Q2d}$.
% Your code goes here.
% Part 2(d) – PD compensator design

s = tf('s');

% Plant
G = 1 / (s*(s+2)*(s+4)*(s+6));

% Desired dominant pole (from part c)
s_d = -1 + 1i; % Hardcoded

% Define G(s) as function handle for complex evaluation
G_s = @(s) 1./(s.*(s+2).*(s+4).*(s+6));

% Solve for real zero z_c so that angle condition is satisfied
fun = @(z) imag((s_d + z) .* G_s(s_d));   % imag of open-loop at s_d must be zero
z_c = fzero(fun, 0)                      % initial guess 0 %[output:1045c5d5]

% Now use magnitude condition |L(s_d)| = 1 to find K
L_noK = (s_d + z_c) .* G_s(s_d);
K = 1 / abs(L_noK) %[output:65668b8b]

% Continuous-time PD compensator D(s) = K (s + z_c)
z_d = []                                 % not used here, keep for completeness %[output:99daa535]
D_Q2d = K * tf([1 z_c], 1) %[output:554d2490]
%[text] **Extra**
%[text] **PI Compensator Design**
% PI compensator design

s = tf('s');

% Plant
G = 1 / (s*(s+2)*(s+4)*(s+6));

% Desired dominant pole
s_d = -1 + 1i;

% Complex evaluation of G(s)
G_s = @(s) 1./(s.*(s+2).*(s+4).*(s+6));

% Solve for zero z_c using angle condition
fun = @(z) imag((s_d + z) ./ s_d .* G_s(s_d));  
% (s_d + z)/s_d is PI structure: (s+z)/s

z_c = fzero(fun, 0);

% Magnitude condition
L_noK = (s_d + z_c) ./ s_d .* G_s(s_d);
K = 1 / abs(L_noK);

% Final PI compensator
D_PI = K * tf([1 z_c], [1 0]) %[output:8d25aac1]
%[text] **Extra**
%[text] **PID Compensator Design**
% PID compensator design

s = tf('s');

% Plant
G = 1 / (s*(s+2)*(s+4)*(s+6));

% Desired dominant pole
s_d = -1 + 1i;

% Complex evaluation of G(s)
G_s = @(s) 1./(s.*(s+2).*(s+4).*(s+6));

% Choose one zero (integral shaping)
z1 = 0.1;   % designer choice

% Solve for second zero z2 using angle condition
fun = @(z2) imag((s_d + z1).*(s_d + z2) ./ s_d .* G_s(s_d));
z2 = fzero(fun, -1);   % initial guess

% Magnitude condition
L_noK = (s_d + z1).*(s_d + z2) ./ s_d .* G_s(s_d);
K = 1 / abs(L_noK);

% Final PID compensator
D_PID = K * tf([1 (z1+z2) z1*z2], [1 0]) %[output:08331cf1]
